// This is deliberately code, not prompt text. Image rights decisions must be
// reproducible from a record and may not be made by a model or an editor's
// free-form status selection.
export const IMAGE_RIGHTS_STATUSES = Object.freeze(['approved', 'rejected', 'manual_review', 'metadata_incomplete']);

export const IMAGE_RIGHTS_POLICY = Object.freeze({
  version: '2026-07-30',
  allowedProviders: Object.freeze({
    wikimedia_commons: Object.freeze({
      label: 'Wikimedia Commons',
      sourcePageDomains: ['commons.wikimedia.org'],
      fileDomains: ['commons.wikimedia.org', 'upload.wikimedia.org'],
      verificationMethods: ['wikimedia_file_page']
    }),
    us_government: Object.freeze({
      label: 'Approved U.S. government collection',
      sourcePageDomains: ['archives.gov', 'loc.gov', 'nasa.gov', 'noaa.gov', 'nps.gov', 'nih.gov', 'si.edu', 'usgs.gov'],
      fileDomains: [],
      verificationMethods: ['government_collection_rights_page']
    }),
    internal_library: Object.freeze({
      label: 'Internal or original media library',
      sourcePageDomains: ['anyways.media'],
      fileDomains: [],
      verificationMethods: ['internal_original_media_record']
    }),
    generated_editorial_illustration: Object.freeze({
      label: 'Generated editorial illustration',
      sourcePageDomains: ['anyways.media'],
      fileDomains: [],
      verificationMethods: ['generated_editorial_illustration']
    })
  }),
  allowedLicenses: Object.freeze({
    public_domain: Object.freeze({ label: 'Public Domain', url: 'https://creativecommons.org/publicdomain/mark/1.0/' }),
    cc0: Object.freeze({ label: 'CC0', url: 'https://creativecommons.org/publicdomain/zero/1.0/' }),
    cc_by: Object.freeze({ label: 'CC BY', url: 'https://creativecommons.org/licenses/by/4.0/' }),
    cc_by_sa: Object.freeze({ label: 'CC BY-SA', url: 'https://creativecommons.org/licenses/by-sa/4.0/' })
  }),
  approvedPressRoomDomains: Object.freeze(['nasa.gov', 'noaa.gov', 'nps.gov', 'nih.gov']),
  requiredMetadataFields: Object.freeze([
    'provider', 'source_page_url', 'original_file_url', 'creator', 'license_code', 'license_url',
    'commercial_use_allowed', 'modification_allowed', 'verification_method', 'verification_timestamp', 'source_metadata'
  ]),
  blockedDomains: Object.freeze([
    'facebook.com', 'instagram.com', 'linkedin.com', 'tiktok.com', 'twitter.com', 'x.com',
    'youtube.com', 'threads.net', 'bsky.app', 'reddit.com', 'pinterest.com'
  ])
});

const compact = value => String(value || '').trim();
const lower = value => compact(value).toLowerCase();
const cleanHost = value => {
  try {
    const url = new URL(compact(value));
    return ['http:', 'https:'].includes(url.protocol) && !url.username && !url.password ? url.hostname.toLowerCase().replace(/^www\./, '') : '';
  } catch { return ''; }
};
const isWithin = (host, domains) => domains.some(domain => host === domain || host.endsWith(`.${domain}`));
const jsonObject = value => value && typeof value === 'object' && !Array.isArray(value);

export function normalizeImageLicense(value) {
  const normalized = lower(value).replace(/[–—-]+/g, '_').replace(/\s+/g, '_');
  const aliases = {
    pd: 'public_domain', 'public_domain': 'public_domain', 'publicdomain': 'public_domain',
    cc0: 'cc0', 'cc_0': 'cc0', 'cc_by': 'cc_by', 'ccby': 'cc_by',
    cc_by_sa: 'cc_by_sa', 'ccby_sa': 'cc_by_sa', 'cc_by_sharealike': 'cc_by_sa'
  };
  return aliases[normalized] || normalized;
}

export function generatedCreditLine(record = {}) {
  return record.provider === 'generated_editorial_illustration' ? 'Illustration: Anyways' : compact(record.credit_line);
}

function decision(status, rule, detail, record, now) {
  const audit = {
    policy_version: IMAGE_RIGHTS_POLICY.version,
    status,
    rule,
    detail,
    checked_at: now,
    metadata_snapshot: structuredClone(record || {})
  };
  return { status, approved: status === 'approved', audit, creditLine: generatedCreditLine(record) };
}

// This function is intentionally exhaustive and deterministic. Callers must
// persist the returned status/audit instead of accepting a supplied status.
export function validateImageRights(record = {}, { now = new Date().toISOString() } = {}) {
  const provider = lower(record.provider);
  const sourcePage = compact(record.source_page_url || record.source_page);
  const originalFile = compact(record.original_file_url || record.original_url);
  const sourceHost = cleanHost(sourcePage);
  const fileHost = cleanHost(originalFile);
  const license = normalizeImageLicense(record.license_code || record.license);
  const providerRule = IMAGE_RIGHTS_POLICY.allowedProviders[provider];

  if (!providerRule) return decision('rejected', 'provider_not_allowed', 'The provider is not in the configured image-policy allowlist.', record, now);
  if (isWithin(sourceHost, IMAGE_RIGHTS_POLICY.blockedDomains) || isWithin(fileHost, IMAGE_RIGHTS_POLICY.blockedDomains)) return decision('rejected', 'social_media_not_allowed', 'Social-media imagery is never eligible for publication.', record, now);
  if (!sourceHost || !fileHost) return decision('metadata_incomplete', 'valid_source_and_file_urls_required', 'Both a source or rights page URL and an original file URL are required.', record, now);
  if (!isWithin(sourceHost, providerRule.sourcePageDomains)) return decision('rejected', 'source_page_not_from_approved_provider', 'The source or rights page is not owned by the configured provider.', record, now);
  if (providerRule.fileDomains.length && !isWithin(fileHost, providerRule.fileDomains)) return decision('rejected', 'original_file_not_from_approved_provider', 'The original file URL is not served by the configured provider.', record, now);
  if (!compact(record.creator)) return decision('metadata_incomplete', 'creator_required', 'Creator metadata is required.', record, now);
  if (!compact(record.license_url) || !cleanHost(record.license_url)) return decision('metadata_incomplete', 'license_url_required', 'A complete license URL is required.', record, now);
  if (!compact(record.verification_method) || !providerRule.verificationMethods.includes(record.verification_method)) return decision('metadata_incomplete', 'provider_verification_method_required', 'The provider-specific verification method is missing or invalid.', record, now);
  if (!compact(record.verification_timestamp) || Number.isNaN(Date.parse(record.verification_timestamp))) return decision('metadata_incomplete', 'verification_timestamp_required', 'A verification timestamp is required.', record, now);
  if (!jsonObject(record.source_metadata) || !Object.keys(record.source_metadata).length) return decision('metadata_incomplete', 'source_metadata_snapshot_required', 'A non-empty source metadata snapshot is required.', record, now);
  if (record.source_metadata.rights_ambiguous === true || record.source_metadata.requires_manual_review === true) return decision('manual_review', 'rights_ambiguity_requires_human_review', 'The source metadata flags an unresolved rights ambiguity.', record, now);
  if (/(^|[_\s-])(nc|nd)([_\s-]|$)/i.test(license)) return decision('rejected', 'noncommercial_or_no_derivatives_license', 'NC and ND licenses are never eligible for publication.', record, now);
  if (!IMAGE_RIGHTS_POLICY.allowedLicenses[license]) return decision('rejected', 'license_not_allowed', 'Only Public Domain, CC0, CC BY, and CC BY-SA are automatically allowed.', record, now);
  if (record.commercial_use_allowed !== true) return decision('rejected', 'commercial_use_not_permitted', 'The record does not confirm commercial-use permission.', record, now);
  if (record.modification_allowed !== true) return decision('rejected', 'modification_not_permitted', 'The record does not confirm permission to modify the image.', record, now);
  if (provider === 'generated_editorial_illustration' && generatedCreditLine(record) !== 'Illustration: Anyways') return decision('rejected', 'generated_credit_required', 'Generated editorial illustrations must use the credit “Illustration: Anyways”.', record, now);
  if (provider === 'generated_editorial_illustration' && record.source_metadata?.documentary === true) return decision('rejected', 'generated_images_cannot_be_documentary', 'Generated illustrations cannot be presented as documentary photography.', record, now);
  return decision('approved', 'approved_provider_license_and_metadata', 'Approved by the configured provider, license, metadata, and permissions rules.', record, now);
}

export function imageMayAttach(record) {
  return validateImageRights(record).status === 'approved';
}
