import { SECTIONS } from '../editorial.mjs';

export const DISCOVERY_FOCUSES = Object.freeze([
  Object.freeze({ id: 'all', label: 'All Web3 sources', description: 'Use every currently eligible source in the Web3 Source Graph.' }),
  ...SECTIONS.map(section => Object.freeze({ id: section.slug, label: section.name, description: section.question }))
]);

export const DISCOVERY_FOCUS_IDS = Object.freeze(DISCOVERY_FOCUSES.map(focus => focus.id));
export const DEFAULT_DISCOVERY_FOCUS_ID = 'all';
export const COMPATIBILITY_DISCOVERY_FOCUS_ID = 'all';

export function validateDiscoveryFocusId(value, { compatibilityDefault = false } = {}) {
  const focusId = value === undefined || value === null || value === ''
    ? (compatibilityDefault ? COMPATIBILITY_DISCOVERY_FOCUS_ID : value)
    : String(value).trim();
  if (!DISCOVERY_FOCUS_IDS.includes(focusId)) throw new Error(`Unknown discovery coverage focus: ${focusId || 'empty'}.`);
  return focusId;
}

export function discoveryFocus(focusId) {
  return DISCOVERY_FOCUSES.find(focus => focus.id === focusId) || null;
}
