export const WRITER_OPTIONS = Object.freeze([
  { value: 'luna-high', label: 'Luna High', model: 'gpt-5.6-luna', reasoning: 'high' },
  { value: 'sol-low', label: 'Sol Low', model: 'gpt-5.6-sol', reasoning: 'low' },
  { value: 'sol-medium', label: 'Sol Medium', model: 'gpt-5.6-sol', reasoning: 'medium' }
]);

export const LENGTH_OPTIONS = Object.freeze([
  { value: 'brief', label: 'Brief' },
  { value: 'standard', label: 'Standard' },
  { value: 'feature', label: 'Feature' }
]);

export const DEFAULT_WRITER_SELECTION = Object.freeze({ writer: 'luna-high', length: 'standard' });

export function writerOption(value) {
  const normalized = String(value || '').trim();
  return WRITER_OPTIONS.find(option => option.value === normalized || option.model === normalized) || WRITER_OPTIONS[0];
}

export function lengthOption(value) {
  return LENGTH_OPTIONS.find(option => option.value === String(value || '').trim()) || LENGTH_OPTIONS[1];
}

export function normalizeWriterSelection(value = {}) {
  const has = key => Object.prototype.hasOwnProperty.call(value, key) && value[key] !== undefined && value[key] !== null;
  const writerInput = has('writer') ? String(value.writer).trim() : '';
  const modelInput = has('writer_model') ? String(value.writer_model).trim() : '';
  const reasoningInput = has('writer_reasoning') ? String(value.writer_reasoning).trim() : '';
  let writerCandidates = writerInput
    ? WRITER_OPTIONS.filter(option => option.value === writerInput)
    : modelInput
      ? WRITER_OPTIONS.filter(option => option.model === modelInput && (!reasoningInput || option.reasoning === reasoningInput))
      : [WRITER_OPTIONS.find(option => option.value === DEFAULT_WRITER_SELECTION.writer)];
  if (writerCandidates.length !== 1) throw new Error('Writer selection is invalid or ambiguous.');
  const writer = writerCandidates[0];
  if (modelInput && modelInput !== writer.model) throw new Error('Writer model does not match the selected writer.');
  if (reasoningInput && reasoningInput !== writer.reasoning) throw new Error('Writer reasoning does not match the selected writer.');
  const lengthInput = has('length') ? String(value.length).trim() : DEFAULT_WRITER_SELECTION.length;
  const length = LENGTH_OPTIONS.find(option => option.value === lengthInput);
  if (!length) throw new Error('Article length is invalid.');
  return { writer: writer.value, length: length.value, model: writer.model, reasoning: writer.reasoning, writer_label: writer.label, length_label: length.label };
}
