import {
  BEAT_ORDER,
  SECTIONS,
  SECTION_ORDER,
  SECTION_PROMISES,
  STORY_FORMS,
  canonicalSectionId,
  canonicalStoryFormId
} from './editorial.mjs';

export const NEWSROOM_LENSES = Object.freeze(SECTIONS.map(section => ({
  id: section.slug,
  name: section.name,
  question: section.question
})));

export const NEWSROOM_SECTIONS = Object.freeze(STORY_FORMS.map(form => ({
  id: form.id,
  name: form.id === 'anyways' ? 'Anyways...' : form.name,
  description: form.purpose,
  minimum: form.minimum,
  maximum: form.maximum
})));

export const NEWSROOM_BEATS = Object.freeze(BEAT_ORDER);

export const EDITOR_STATUS_LABELS = Object.freeze({
  pitch_ready: 'Pitch Selected',
  approved: 'Approved',
  acquiring_sources: 'Sources Acquired',
  research_ready: 'Research Ready',
  research_blocked: 'Needs Attention',
  evidence_ready: 'Evidence Frozen',
  drafting: 'Luna Draft',
  ready_for_review: 'AI Review',
  ai_review_ready: 'AI Review',
  verification_failed: 'Needs Attention',
  revision_requested: 'Needs Attention',
  failed: 'Needs Attention',
  fact_check: 'On Deck',
  scheduled: 'Scheduled',
  published: 'Published',
  hidden: 'Hidden',
  archived: 'Archived',
  rejected_by_editor: 'Rejected'
});

export const PIPELINE_STAGE_LABELS = Object.freeze([
  'Discovery',
  'Pitch Selected',
  'Sources Acquired',
  'Research Decision',
  'Evidence Frozen',
  'Luna Draft',
  'Deterministic Validation',
  'AI Review',
  'Optional Sol Polish',
  'On Deck',
  'Published'
]);

export function editorStatusLabel(value) {
  const status = String(value || '').trim();
  return EDITOR_STATUS_LABELS[status] || status.replace(/_/g, ' ').replace(/\b\w/g, char => char.toUpperCase());
}

export function lensLabel(value) {
  const id = canonicalSectionId(value);
  return NEWSROOM_LENSES.find(item => item.id === id)?.name || (value ? String(value).replace(/[-_]/g, ' ').replace(/\b\w/g, char => char.toUpperCase()) : 'Not assigned');
}

export function sectionLabel(value) {
  const id = canonicalStoryFormId(value);
  if (String(value || '').trim().toLowerCase() === 'systems') return 'Anyways...';
  return NEWSROOM_SECTIONS.find(item => item.id === id)?.name || (value ? String(value).replace(/[-_]/g, ' ').replace(/\b\w/g, char => char.toUpperCase()) : 'Not assigned');
}

export function beatLabel(value) {
  return String(value || '').replace(/[-_]/g, ' ').replace(/\b\w/g, char => char.toUpperCase());
}

export function topicLabel(value) {
  return String(value || '').replace(/[-_]/g, ' ').trim();
}

export function modelLabel(model = '', stage = '') {
  const value = String(model || '').toLowerCase();
  const currentStage = String(stage || '').toLowerCase();
  if (value.includes('terra') || currentStage.includes('research')) return 'Terra High';
  if (value.includes('sol') || currentStage.includes('polish')) return 'Sol Medium';
  if (value.includes('luna') || currentStage.includes('draft') || currentStage.includes('discovery') || currentStage.includes('pitch')) return 'Luna High';
  return 'Editorial pipeline';
}

export function pipelineStageIndex({ candidateStatus = '', hasSources = false, hasPacket = false, hasDraft = false, hasReview = false, hasOnDeck = false, published = false } = {}) {
  if (published) return PIPELINE_STAGE_LABELS.length - 1;
  if (hasOnDeck) return PIPELINE_STAGE_LABELS.indexOf('On Deck');
  if (hasReview) return PIPELINE_STAGE_LABELS.indexOf('AI Review');
  if (hasDraft) return PIPELINE_STAGE_LABELS.indexOf('Deterministic Validation');
  if (hasPacket) return PIPELINE_STAGE_LABELS.indexOf('Luna Draft') - 1;
  if (hasSources) return PIPELINE_STAGE_LABELS.indexOf('Sources Acquired');
  if (candidateStatus === 'pitch_ready') return PIPELINE_STAGE_LABELS.indexOf('Pitch Selected');
  return 0;
}
