/**
 * The newsroom stores several operational states because the controller,
 * review package, and publication editor have different responsibilities.
 * This is the one UI-facing translation layer. Models and workers never write
 * this value, and the ordering below is intentionally explicit.
 */
export const EDITORIAL_STATUSES = Object.freeze([
  'pitch',
  'commissioned',
  'writing',
  'draft',
  'needs_attention',
  'ready',
  'scheduled',
  'published',
  'archived',
  'failed'
]);

export const EDITORIAL_STATUS_LABELS = Object.freeze({
  pitch: 'Pitch',
  commissioned: 'Commissioned',
  writing: 'Writing',
  draft: 'Draft',
  needs_attention: 'Needs attention',
  ready: 'Ready',
  scheduled: 'Scheduled',
  published: 'Published',
  archived: 'Archived',
  failed: 'Failed'
});

const ACTIVE_JOB_STATUSES = new Set(['queued', 'claimed', 'running']);
const FAILED_JOB_STATUSES = new Set(['failed']);
const READY_CANDIDATE_STATUSES = new Set(['ready_for_review', 'ai_review_ready', 'approved']);
const ARCHIVED_CANDIDATE_STATUSES = new Set(['archived', 'rejected_by_editor', 'deleted']);

const array = value => Array.isArray(value) ? value : [];
const text = value => String(value ?? '').trim();

function candidateBlockers(candidate = {}, review = {}) {
  const classification = candidate.classification || {};
  const phase2 = classification.phase2 || classification.phase2_review || {};
  const blockers = [
    ...array(classification.blockers),
    ...array(classification.review_blockers),
    ...array(classification.editorial_pitch?.blockers),
    ...array(phase2.blockers),
    ...array(review.blockers),
    ...array(review.blocking_factual_errors)
  ];
  const unresolvedClaims = Number(
    candidate.unresolved_claim_count
      ?? classification.unresolved_claim_count
      ?? review.unresolved_claim_count
      ?? 0
  );
  const statusBlocked = new Set(['research_blocked', 'verification_failed', 'revision_requested']).has(text(candidate.status));
  const phaseBlocked = new Set(['research_blocked', 'blocked', 'verification_failed']).has(text(classification.phase2_state || phase2.state));
  const reviewBlocked = text(review.status).toLowerCase() === 'blocked';
  return statusBlocked || phaseBlocked || reviewBlocked || unresolvedClaims > 0 || blockers.length > 0;
}

function jobsFor({ job = null, jobs = [] } = {}) {
  return [job, ...array(jobs)].filter(Boolean);
}

function hasFailedJob(records) {
  return records.some(item => FAILED_JOB_STATUSES.has(text(item.status)));
}

function hasActiveJob(records) {
  return records.some(item => ACTIVE_JOB_STATUSES.has(text(item.status)));
}

function isResearchAgainJob(job = {}) {
  return job?.job_type === 'process_candidate'
    && ['v1', 'pipeline-v1'].includes(text(job.parameters?.pipeline_version))
    && text(job.parameters?.authorization) === 'research_again';
}

function hasDraft({ story = {}, draft = {}, candidate = {} } = {}) {
  return Boolean(text(story.body || draft.body_markdown || draft.body || candidate.draft?.body_markdown));
}

function isPublished({ story = {}, publication = {} } = {}) {
  return Boolean(story.published_at || publication.published_at) || text(story.status) === 'published' || text(publication.status) === 'published';
}

function isScheduled({ story = {}, publication = {} } = {}) {
  return Boolean(story.scheduled_for || publication.scheduled_for) || text(story.status) === 'scheduled' || text(publication.status) === 'scheduled';
}

export function deriveEditorialStatus({ story = {}, candidate = {}, job = null, jobs = [], review = {}, draft = {}, publication = {} } = {}) {
  const operationalJobs = jobsFor({ job, jobs });
  const storyStatus = text(story.status);
  const candidateStatus = text(candidate.status);

  // Precedence is highest to lowest: publication, archive, failed execution,
  // unresolved editorial blockers, active execution, ready review handoff,
  // saved draft, commission, then an uncommissioned pitch.
  if (isPublished({ story, publication })) return 'published';
  if (isScheduled({ story, publication })) return 'scheduled';
  if (storyStatus === 'archived' || storyStatus === 'hidden' || ARCHIVED_CANDIDATE_STATUSES.has(candidateStatus)) return 'archived';
  if (hasActiveJob(operationalJobs) && operationalJobs.some(isResearchAgainJob)) return 'writing';
  if (candidateStatus === 'failed' || hasFailedJob(operationalJobs)) return 'failed';
  if (candidateBlockers(candidate, review)) return 'needs_attention';
  if (hasActiveJob(operationalJobs)) return 'writing';
  if (storyStatus === 'fact_check' || storyStatus === 'review' || READY_CANDIDATE_STATUSES.has(candidateStatus) || text(review.status) === 'ready_for_review') return 'ready';
  if (hasDraft({ story, draft, candidate }) || storyStatus === 'draft') return 'draft';

  const pitch = candidate.classification?.editorial_pitch || {};
  const commissioned = Boolean(
    candidate.commission
      || candidate.classification?.editorial_assignment
      || pitch.commissioned === true
      || pitch.commissioned_by
      || pitch.commissioned_job_id
      || ['researching', 'ready_to_draft', 'drafting', 'editing'].includes(candidateStatus)
      || storyStatus === 'researching'
  );
  if (commissioned) return 'commissioned';
  return 'pitch';
}

export function editorialStatusLabel(status) {
  const value = text(status);
  return EDITORIAL_STATUS_LABELS[value] || (value ? value.replace(/[_-]+/g, ' ').replace(/\b\w/g, letter => letter.toUpperCase()) : EDITORIAL_STATUS_LABELS.pitch);
}

export function editorialBlockingIssue({ candidate = {}, job = null, jobs = [], review = {} } = {}) {
  const failed = jobsFor({ job, jobs }).find(item => FAILED_JOB_STATUSES.has(text(item.status)));
  if (failed?.error?.message) return text(failed.error.message);
  if (candidate.classification?.phase2?.blockers?.[0]) return text(candidate.classification.phase2.blockers[0].reason || candidate.classification.phase2.blockers[0]);
  if (review.blocking_factual_errors?.[0]) return text(review.blocking_factual_errors[0]);
  if (Number(candidate.unresolved_claim_count || candidate.classification?.unresolved_claim_count || 0) > 0) return 'Claims still need verification.';
  if (['research_blocked', 'verification_failed', 'revision_requested'].includes(text(candidate.status))) return 'Editorial review is required before this can move forward.';
  return '';
}

export function editorialActivityDate({ story = {}, candidate = {}, job = null, jobs = [], review = {}, publication = {} } = {}) {
  const values = [
    story.updated_at,
    candidate.updated_at,
    candidate.created_at,
    publication.published_at,
    publication.scheduled_for,
    review.updated_at,
    review.created_at,
    ...jobsFor({ job, jobs }).flatMap(item => [item.finished_at, item.started_at, item.created_at])
  ].filter(Boolean).map(value => new Date(value).getTime()).filter(Number.isFinite);
  return values.length ? new Date(Math.max(...values)).toISOString() : null;
}
