const ACTIVE = new Set(['queued', 'claimed', 'running']);
const text = value => String(value ?? '').trim();

function windowed(records, since) {
  return records.filter(record => {
    const at = Date.parse(record.finished_at || record.started_at || record.created_at || record.timestamp || '');
    return Number.isFinite(at) && at >= since;
  });
}

function median(values) {
  const sorted = values.filter(Number.isFinite).sort((a, b) => a - b);
  if (!sorted.length) return null;
  const middle = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2;
}

export function aggregatePipelineHealth({ jobs = [], attempts = [], now = Date.now() } = {}) {
  const summarize = (hours) => {
    const since = now - hours * 60 * 60 * 1000;
    const rows = windowed(jobs, since);
    const stageRows = windowed(attempts, since);
    const counts = { total_jobs: rows.length, succeeded: 0, empty: 0, provider_error: 0, failed: 0, queued_or_running: rows.filter(job => ACTIVE.has(text(job.status))).length };
    const failuresByStage = {};
    const failuresByCategory = {};
    const providerCounts = {};
    const writerCounts = {};
    for (const job of rows) {
      const status = text(job.status);
      const result = job.result || {};
      const error = job.error || result.error || result.result?.error || {};
      const empty = result.research_empty === true || result.result?.research_empty === true || error.category === 'empty_result';
      const providerError = Boolean(error.category && error.category !== 'empty_result' && String(error.category).startsWith('provider')) || error.normalized_provider_error;
      if (empty) counts.empty += 1;
      if (providerError) counts.provider_error += 1;
      if (!empty && !providerError && status === 'completed') counts.succeeded += 1;
      if (status === 'failed') counts.failed += 1;
      if (status === 'failed' || providerError) {
        const stage = text(error.details?.stage || error.stage || 'unknown');
        const category = text(error.category || error.details?.normalized_provider_error?.category || error.code || 'unknown');
        failuresByStage[stage] = (failuresByStage[stage] || 0) + 1;
        failuresByCategory[category] = (failuresByCategory[category] || 0) + 1;
      }
      const writer = text(job.parameters?.writer || job.parameters?.writer_model);
      if (writer) {
        writerCounts[writer] ||= { success: 0, error: 0 };
        if (status === 'completed' && !empty && !providerError) writerCounts[writer].success += 1;
        if (status === 'failed' || providerError) writerCounts[writer].error += 1;
      }
    }
    for (const attempt of stageRows) {
      const provider = text(attempt.provider || attempt.provider_configuration?.provider);
      if (provider) {
        providerCounts[provider] ||= { success: 0, error: 0 };
        if (attempt.status === 'complete' && attempt.provider_result_status !== 'empty') providerCounts[provider].success += 1;
        if (attempt.status === 'failed' || attempt.provider_result_status === 'provider_error') providerCounts[provider].error += 1;
      }
    }
    const completed = counts.succeeded + counts.empty + counts.provider_error + counts.failed;
    return { window_hours: hours, ...counts, success_rate: completed ? counts.succeeded / completed : 0, empty_result_rate: completed ? counts.empty / completed : 0, provider_error_rate: completed ? counts.provider_error / completed : 0, failed_rate: completed ? counts.failed / completed : 0, median_stage_duration_ms: median(stageRows.map(stageDuration)), failures_by_stage: failuresByStage, failures_by_category: failuresByCategory, provider_counts: providerCounts, writer_counts: writerCounts };
  };
  return { last_24_hours: summarize(24), last_7_days: summarize(24 * 7) };
}

function stageDuration(attempt = {}) {
  if (Number.isFinite(attempt.runtime_ms)) return attempt.runtime_ms;
  const start = Date.parse(attempt.started_at || '');
  const end = Date.parse(attempt.finished_at || '');
  return Number.isFinite(start) && Number.isFinite(end) ? Math.max(0, end - start) : null;
}
