const text = value => String(value ?? '').trim();

function statusFor(attempt) {
  if (attempt?.superseded || attempt?.status === 'superseded') return 'superseded';
  if (attempt?.provider_result_status === 'empty' || attempt?.final_stage_classification === 'empty_result') return 'empty';
  if (attempt?.status === 'running') return 'running';
  if (attempt?.status === 'complete' || attempt?.final_stage_classification === 'completed') return 'succeeded';
  if (attempt?.normalized_provider_error || attempt?.provider_result_status === 'provider_error') return 'needs attention';
  if (attempt?.status === 'failed') return 'failed';
  return text(attempt?.status) || 'queued';
}

export function stageDuration(attempt = {}) {
  if (Number.isFinite(attempt.runtime_ms)) return Math.max(0, attempt.runtime_ms);
  const start = Date.parse(attempt.started_at || '');
  const end = Date.parse(attempt.finished_at || attempt.completed_at || '');
  return Number.isFinite(start) && Number.isFinite(end) ? Math.max(0, end - start) : null;
}

export function executionTimeline({ attempts = [], events = [] } = {}) {
  const latestByStage = new Map();
  for (const attempt of attempts) {
    const key = text(attempt.stage);
    if (!key) continue;
    const current = latestByStage.get(key);
    if (!current || Number(attempt.attempt || 0) > Number(current.attempt || 0)) latestByStage.set(key, attempt);
  }
  const attemptRows = attempts.map(attempt => {
    const latest = latestByStage.get(text(attempt.stage));
    const superseded = Boolean(latest && latest !== attempt && Number(attempt.attempt || 0) < Number(latest.attempt || 0));
    return {
      stage: text(attempt.stage), status: statusFor({ ...attempt, superseded }), timestamp: attempt.started_at || attempt.created_at || null,
      completed_at: attempt.finished_at || null, duration_ms: stageDuration(attempt), attempt: Number(attempt.attempt || 1),
      provider: attempt.provider || attempt.adapter_diagnostics?.provider || null,
      writer: attempt.writer || attempt.provider_configuration?.writer || null,
      result: attempt.empty_result_reason || attempt.error?.message || attempt.normalized_provider_error?.category || (attempt.status === 'complete' ? 'Stage completed.' : 'Stage recorded.'),
      diagnostics: { parse_outcome: attempt.parse_outcome, schema_outcome: attempt.schema_outcome, empty_result_reason: attempt.empty_result_reason || null, provider_error: attempt.normalized_provider_error || null, validation_errors: attempt.validation_errors || [], provider_attempts: attempt.provider_attempts || [] }
    };
  });
  const eventRows = events.filter(event => event?.at).map(event => ({ stage: text(event.stage || event.type || 'pipeline'), status: text(event.type) === 'stage_empty' ? 'empty' : text(event.type) === 'stage_failed' ? 'failed' : 'succeeded', timestamp: event.at, completed_at: event.at, duration_ms: null, attempt: Number(event.attempt || 1), provider: event.provider || null, writer: null, result: event.message || text(event.type), diagnostics: event }));
  return [...attemptRows, ...eventRows].sort((a, b) => new Date(a.timestamp || 0) - new Date(b.timestamp || 0));
}
