export const PHOTO_IMAGE_TIMEOUT_MS = 12_000;
export const PHOTO_UPLOAD_TIMEOUT_MS = 45_000;
export const PHOTO_RECORD_TIMEOUT_MS = 20_000;
export const PHOTO_CLEANUP_TIMEOUT_MS = 8_000;
export const PHOTO_OPTIMIZATION_MAX_EDGE = 2000;
export const PHOTO_OPTIMIZATION_QUALITY = 0.84;

const OPTIMIZABLE_PHOTO_TYPES = new Set(['image/jpeg', 'image/png', 'image/webp']);

function optimizedFilename(name) {
  const base = String(name || 'photo').replace(/\.[^.]+$/, '') || 'photo';
  return `${base}.webp`;
}

/* Keep the newsroom upload simple for editors: large still images are resized
   and encoded once in the browser before they reach storage. Animated GIFs and
   AVIFs stay untouched because converting them can change their meaning or
   animation support. Any browser/canvas failure falls back to the source file. */
export async function preparePhotoUpload(file, {
  maxEdge = PHOTO_OPTIMIZATION_MAX_EDGE,
  quality = PHOTO_OPTIMIZATION_QUALITY,
  createBitmap = typeof globalThis.createImageBitmap === 'function' ? globalThis.createImageBitmap.bind(globalThis) : null,
  canvasFactory = () => globalThis.document?.createElement?.('canvas'),
  fileFactory = (parts, name, options) => typeof globalThis.File === 'function' ? new globalThis.File(parts, name, options) : null
} = {}) {
  const original = { file, optimized: false, width: null, height: null, originalBytes: Number(file?.size) || 0, optimizedBytes: Number(file?.size) || 0 };
  const mimeType = String(file?.type || '').toLowerCase();
  if (!file || !OPTIMIZABLE_PHOTO_TYPES.has(mimeType) || typeof createBitmap !== 'function') return original;

  let bitmap;
  try {
    try { bitmap = await createBitmap(file, { imageOrientation: 'from-image' }); }
    catch { bitmap = await createBitmap(file); }
    const sourceWidth = Number(bitmap?.width) || 0;
    const sourceHeight = Number(bitmap?.height) || 0;
    if (!sourceWidth || !sourceHeight) return original;
    const scale = Math.min(1, Number(maxEdge) / Math.max(sourceWidth, sourceHeight));
    const width = Math.max(1, Math.round(sourceWidth * scale));
    const height = Math.max(1, Math.round(sourceHeight * scale));
    if (scale === 1 && Number(file.size) <= 180 * 1024) return { ...original, width, height };

    const canvas = canvasFactory();
    const context = canvas?.getContext?.('2d', { alpha: true });
    if (!canvas || !context || typeof canvas.toBlob !== 'function') return { ...original, width, height };
    canvas.width = width;
    canvas.height = height;
    context.drawImage(bitmap, 0, 0, width, height);
    const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/webp', quality));
    if (!blob || !blob.size) return { ...original, width, height };
    if (scale === 1 && blob.size >= Number(file.size || 0)) return { ...original, width, height };
    const optimized = fileFactory([blob], optimizedFilename(file.name), { type: 'image/webp', lastModified: file.lastModified || Date.now() });
    if (!optimized) return { ...original, width, height };
    return { file: optimized, optimized: true, width, height, originalBytes: Number(file.size) || 0, optimizedBytes: optimized.size };
  } catch {
    return original;
  } finally {
    try { bitmap?.close?.(); } catch {}
  }
}

export function withPhotoTimeout(work, timeoutMs, message, { onTimeout, setTimer = setTimeout, clearTimer = clearTimeout } = {}) {
  let timer;
  const timeout = new Promise((_, reject) => {
    timer = setTimer(() => {
      try { onTimeout?.(); } catch {}
      reject(new Error(message));
    }, timeoutMs);
  });
  return Promise.race([Promise.resolve(work), timeout]).finally(() => clearTimer(timer));
}

export function inspectPhotoSource(source, {
  revoke = false,
  timeoutMs = PHOTO_IMAGE_TIMEOUT_MS,
  imageFactory = () => new Image(),
  revokeObjectUrl = value => URL.revokeObjectURL(value),
  setTimer = setTimeout,
  clearTimer = clearTimeout
} = {}) {
  return new Promise(resolve => {
    const image = imageFactory();
    let settled = false;
    let timer;
    const finish = dimensions => {
      if (settled) return;
      settled = true;
      clearTimer(timer);
      image.onload = null;
      image.onerror = null;
      if (revoke) {
        try { revokeObjectUrl(source); } catch {}
      }
      resolve(dimensions);
    };
    image.onload = () => finish({ width: image.naturalWidth || null, height: image.naturalHeight || null, timedOut: false });
    image.onerror = () => finish({ width: null, height: null, timedOut: false });
    timer = setTimer(() => {
      finish({ width: null, height: null, timedOut: true });
      try { image.src = ''; } catch {}
    }, timeoutMs);
    try {
      image.src = source;
    } catch {
      finish({ width: null, height: null, timedOut: false });
    }
  });
}

export function inspectVideoSource(source, {
  revoke = false,
  timeoutMs = PHOTO_IMAGE_TIMEOUT_MS,
  videoFactory = () => document.createElement('video'),
  revokeObjectUrl = value => URL.revokeObjectURL(value),
  setTimer = setTimeout,
  clearTimer = clearTimeout
} = {}) {
  return new Promise(resolve => {
    const video = videoFactory();
    let settled = false;
    let timer;
    const finish = dimensions => {
      if (settled) return;
      settled = true;
      clearTimer(timer);
      video.onloadedmetadata = null;
      video.onerror = null;
      if (revoke) {
        try { revokeObjectUrl(source); } catch {}
      }
      resolve(dimensions);
    };
    video.preload = 'metadata';
    video.onloadedmetadata = () => finish({ width: video.videoWidth || null, height: video.videoHeight || null, timedOut: false });
    video.onerror = () => finish({ width: null, height: null, timedOut: false });
    timer = setTimer(() => {
      finish({ width: null, height: null, timedOut: true });
      try { video.removeAttribute('src'); video.load?.(); } catch {}
    }, timeoutMs);
    try {
      video.src = source;
    } catch {
      finish({ width: null, height: null, timedOut: false });
    }
  });
}
