import { BEAT_ORDER, SECTION_ORDER, STORY_FORM_ORDER } from './editorial.mjs';

export const ARTICLE_COMMISSION_LIMITS = Object.freeze({
  brief: 3000,
  notes: 4000,
  sources: 20,
  beats: 8,
  tags: 12
});

const PRIVATE_HOST = /(^localhost$|\.local$|\.internal$|^127\.|^10\.|^0\.|^169\.254\.|^192\.168\.|^172\.(1[6-9]|2\d|3[01])\.)/i;
const cleanText = (value, limit) => String(value || '').trim().replace(/\r\n/g, '\n').slice(0, limit + 1);
const values = value => Array.isArray(value) ? value : String(value || '').split(/[\n,]/);
const sourceValues = value => Array.isArray(value) ? value : String(value || '').split(/\n/);
const unique = items => [...new Set(items)];

function sourceUrl(value) {
  let url;
  try { url = new URL(String(value).trim()); } catch { throw new Error(`Source link is not a valid URL: ${value}`); }
  if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password || PRIVATE_HOST.test(url.hostname)) {
    throw new Error(`Source links must be public http(s) URLs: ${value}`);
  }
  url.hash = '';
  return url.toString();
}

function tag(value) {
  const cleaned = String(value || '').trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  if (!cleaned || cleaned.length > 50) throw new Error('Tags must be short, readable topic labels.');
  return cleaned;
}

export function validateArticleCommission(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('A valid article request is required.');
  const brief = cleanText(value.brief, ARTICLE_COMMISSION_LIMITS.brief);
  if (brief.length < 20) throw new Error('Give the writer a clear article request of at least 20 characters.');
  if (brief.length > ARTICLE_COMMISSION_LIMITS.brief) throw new Error(`Article requests are limited to ${ARTICLE_COMMISSION_LIMITS.brief} characters.`);
  const section_id = String(value.section_id || '').trim();
  if (!SECTION_ORDER.includes(section_id)) throw new Error('Choose one primary lens.');
  // The form is mandatory in the current Newsroom UI. A small compatibility
  // fallback lets assignments submitted before that field existed be retried
  // instead of becoming permanently unrecoverable queue records.
  const story_form = String(value.story_form || 'while-youre-here').trim();
  if (!STORY_FORM_ORDER.includes(story_form)) throw new Error('Choose the optional section the reporting should support.');
  const beats = unique(values(value.beats).map(item => String(item).trim()).filter(Boolean));
  if (beats.length > ARTICLE_COMMISSION_LIMITS.beats || beats.some(item => !BEAT_ORDER.includes(item))) throw new Error('Choose only the approved recurring beats.');
  const tags = unique(values(value.tags).map(item => String(item).trim()).filter(Boolean).map(tag));
  if (tags.length > ARTICLE_COMMISSION_LIMITS.tags) throw new Error(`Use no more than ${ARTICLE_COMMISSION_LIMITS.tags} tags.`);
  const source_urls = unique(sourceValues(value.source_urls).map(item => String(item).trim()).filter(Boolean).map(sourceUrl));
  if (!source_urls.length) throw new Error('Add at least one source link so the source-first writer has evidence to work from.');
  if (source_urls.length > ARTICLE_COMMISSION_LIMITS.sources) throw new Error(`Add no more than ${ARTICLE_COMMISSION_LIMITS.sources} source links.`);
  const notes = cleanText(value.notes, ARTICLE_COMMISSION_LIMITS.notes);
  if (notes.length > ARTICLE_COMMISSION_LIMITS.notes) throw new Error(`Supporting notes are limited to ${ARTICLE_COMMISSION_LIMITS.notes} characters.`);
  return { brief, section_id, story_form, beats, tags, source_urls, notes };
}
