import { ARTICLE_LENGTH_ORDER, SECTION_ORDER, SIGNIFICANCE_TEST, canonicalSectionId } from '../editorial.mjs';

export const IDEA_PITCH_PROMPT_VERSION = 'ideas-pitches-v1';
export const IDEA_PITCH_COUNT = Object.freeze({ min: 3, max: 5 });

const clean = value => String(value || '').replace(/\s+/g, ' ').trim();
const list = value => Array.isArray(value) ? value.map(clean).filter(Boolean) : [];

export function buildIdeaPitchesPrompt({ idea } = {}) {
  const prompt = clean(idea).slice(0, 2000);
  if (prompt.length < 12) throw new Error('An editorial idea needs at least 12 characters.');
  return `You are Luna, the final editorial decision-maker for Anyways, a Web3-native publication. Turn the editor's loose idea into 3 to 5 distinct, sourceable editorial pitches. Interpret the idea rather than repeating it. Avoid near-duplicate angles, generic trend pieces, token-price updates, launch coverage without a larger consequence, and invented reporting.

Return one JSON object only with this exact shape:
{"pitches":[{"headline":"","angle":"","why_now":"","audience":"","primary_section":"","topics":[],"recommended_length":"brief|standard|feature","research_limitation":"","primary_source":"","source_urls":[],"confidence":0,"newness":0,"editorial_score":0,"ready_now":false,"reasoning_summary":"","significance_tests":[]}]}

For every pitch:
- headline is a proposed headline, not a source headline;
- angle is one sentence that says what the story would reveal;
- why_now explains the timely trigger;
- audience names who cares;
- primary_section is one of: ${SECTION_ORDER.join(', ')};
- topics are narrow Web3 topic labels;
- recommended_length is brief, standard, or feature;
- research_limitation is concise and honest;
- primary_source and source_urls must be empty when no source is actually known; never invent a URL;
- confidence, newness, and editorial_score are numbers from 0 to 10;
- ready_now is true only when the pitch can be commissioned from the retained evidence;
- reasoning_summary is concise editorial rationale, never private chain-of-thought;
- significance_tests contains at least two exact questions from: ${SIGNIFICANCE_TEST.join(' | ')}.

EDITOR IDEA
${prompt}`;
}
function normalizePitch(value, index) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`Idea pitch ${index + 1} is not an object.`);
  const headline = clean(value.headline).slice(0, 180);
  const angle = clean(value.angle).slice(0, 600);
  const why_now = clean(value.why_now).slice(0, 600);
  const audience = clean(value.audience).slice(0, 240);
  const primary_section = canonicalSectionId(value.primary_section);
  const topics = list(value.topics).slice(0, 12);
  const recommended_length = clean(value.recommended_length).toLowerCase();
  const research_limitation = clean(value.research_limitation).slice(0, 600);
  const primary_source = clean(value.primary_source).slice(0, 2048);
  const source_urls = list(value.source_urls).slice(0, 20);
  const confidence = Number(value.confidence);
  const newness = Number(value.newness);
  const editorial_score = Number(value.editorial_score);
  const reasoning_summary = clean(value.reasoning_summary).slice(0, 600);
  const significance_tests = list(value.significance_tests);
  if (!headline || !angle || !why_now || !audience || !SECTION_ORDER.includes(primary_section)) throw new Error(`Idea pitch ${index + 1} is missing required editorial fields.`);
  if (!ARTICLE_LENGTH_ORDER.includes(recommended_length)) throw new Error(`Idea pitch ${index + 1} selected an invalid length.`);
  if (![confidence, newness, editorial_score].every(number => Number.isFinite(number) && number >= 0 && number <= 10)) throw new Error(`Idea pitch ${index + 1} has an invalid score.`);
  if (source_urls.some(url => !/^https?:\/\/[^\s]+$/i.test(url))) throw new Error(`Idea pitch ${index + 1} contains an invalid source URL.`);
  if (significance_tests.length < 2 || significance_tests.some(test => !SIGNIFICANCE_TEST.includes(test))) throw new Error(`Idea pitch ${index + 1} needs two canonical editorial questions.`);
  return { headline, angle, why_now, audience, primary_section, topics, recommended_length, research_limitation, primary_source, source_urls, confidence, newness, editorial_score, ready_now: value.ready_now === true, reasoning_summary, significance_tests, prompt_version: IDEA_PITCH_PROMPT_VERSION, position: index + 1 };
}

export function parseIdeaPitches(raw) {
  const text = String(raw || '').trim();
  if (!text.startsWith('{') || !text.endsWith('}')) throw new Error('Idea pitch generation must return one JSON object.');
  let parsed;
  try { parsed = JSON.parse(text); } catch { throw new Error('Idea pitch generation returned invalid JSON.'); }
  if (!Array.isArray(parsed?.pitches) || parsed.pitches.length < IDEA_PITCH_COUNT.min || parsed.pitches.length > IDEA_PITCH_COUNT.max) throw new Error('Idea pitch generation must return 3 to 5 pitches.');
  const pitches = parsed.pitches.map(normalizePitch);
  const headlines = new Set(pitches.map(pitch => pitch.headline.toLowerCase()));
  if (headlines.size !== pitches.length) throw new Error('Idea pitch generation returned duplicate headlines.');
  return pitches;
}

export function mockIdeaPitches(idea) {
  const subject = clean(idea).replace(/[.!?]+$/, '').slice(0, 110) || 'the editor idea';
  const base = { confidence: 4, newness: 5, editorial_score: 6, ready_now: false, primary_source: '', source_urls: [], prompt_version: `${IDEA_PITCH_PROMPT_VERSION}-local-preview`, significance_tests: ['is it actually new?', 'who cares?'] };
  return [
    { ...base, position: 1, headline: `${subject}: the product story underneath the announcement`, angle: `Follow the behavior this idea changes, then show what the product reveals about how Web3 is becoming useful or legible to more people.`, why_now: 'The idea points to a live shift, but the timely trigger still needs to be verified against primary sources.', audience: 'Readers tracking products, users, and the practical edge of Web3.', primary_section: 'products', topics: ['product strategy'], recommended_length: 'standard', research_limitation: 'Preview only. Verify the product change, user behavior, and primary source before commissioning.', reasoning_summary: 'A product-led angle that looks for behavior instead of repeating the announcement.' },
    { ...base, position: 2, headline: `${subject}: who gets to define the next Web3 audience`, angle: `Examine the audience being pursued and the social or cultural bargain being offered beyond the usual crypto-native user.`, why_now: 'The audience claim is plausible but requires current evidence about adoption, identity, and distribution.', audience: 'Readers interested in internet culture, communities, and adoption.', primary_section: 'culture', topics: ['communities', 'brands'], recommended_length: 'brief', research_limitation: 'Needs interviews or first-party usage evidence to distinguish positioning from real adoption.', reasoning_summary: 'A culture angle that tests whether the audience shift is real or merely a new marketing frame.' },
    { ...base, position: 3, headline: `${subject}: the market signal hiding in plain sight`, angle: `Trace where capital, liquidity, or attention moves when this idea becomes real, and identify who gains leverage from that movement.`, why_now: 'The market consequence is a hypothesis until current data and a primary source establish the change.', audience: 'Readers who want the market implication without a price-only story.', primary_section: 'markets', topics: ['market structure'], recommended_length: 'feature', research_limitation: 'Requires current market data and at least one primary filing, dashboard, or company source.', reasoning_summary: 'A market-structure angle that avoids turning a meaningful question into a token-price update.' }
  ];
}
