export const REPLAY_STAGES = Object.freeze(['research', 'packet', 'writer', 'review']);

const STAGE_MAP = Object.freeze({
  research: { canonical_stage: 'research', reuse: ['source_inventory'], rerun: ['research', 'evidence_packet', 'draft', 'draft_review', 'ai_review'] },
  packet: { canonical_stage: 'evidence_packet', reuse: ['source_inventory', 'research'], rerun: ['evidence_packet', 'draft', 'draft_review', 'ai_review'] },
  writer: { canonical_stage: 'draft', reuse: ['source_inventory', 'research', 'evidence_packet'], rerun: ['draft', 'draft_review', 'ai_review'] },
  review: { canonical_stage: 'ai_review', reuse: ['source_inventory', 'research', 'evidence_packet', 'draft', 'draft_review'], rerun: ['ai_review'] }
});

const uuid = () => {
  if (globalThis.crypto?.randomUUID) return globalThis.crypto.randomUUID();
  const bytes = new Uint8Array(16);
  if (globalThis.crypto?.getRandomValues) globalThis.crypto.getRandomValues(bytes);
  else for (let index = 0; index < bytes.length; index += 1) bytes[index] = Math.floor(Math.random() * 256);
  bytes[6] = (bytes[6] & 0x0f) | 0x40;
  bytes[8] = (bytes[8] & 0x3f) | 0x80;
  const hex = [...bytes].map(value => value.toString(16).padStart(2, '0')).join('');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
};

export function replayPlan(stage) {
  const plan = STAGE_MAP[String(stage || '').trim()];
  if (!plan) throw new Error(`Replay is not available from stage: ${stage || '(missing)'}`);
  return { requested_stage: stage, ...plan, reuse: [...plan.reuse], rerun: [...plan.rerun] };
}

export function replayEligibility({ candidate = {}, run = null, stage, activeJobs = [] } = {}) {
  const plan = replayPlan(stage);
  if (!run || !['failed', 'blocked'].includes(run.status)) return { eligible: false, reason: 'Replay requires a failed or blocked Phase 2 run.', plan };
  if (['published', 'scheduled'].includes(candidate?.status) || candidate?.published_at || candidate?.scheduled_for) return { eligible: false, reason: 'Published and scheduled stories cannot be replayed from a failed stage.', plan };
  if (activeJobs.some(job => ['queued', 'claimed', 'running'].includes(job.status) && job.parameters?.candidate_id === (candidate.external_id || candidate.id))) return { eligible: false, reason: 'An active job already exists for this candidate.', plan };
  return { eligible: true, reason: '', plan };
}

export function createReplayAuthorization({ candidate = {}, run, stage, jobId, writerSelection = null } = {}) {
  const eligibility = replayEligibility({ candidate, run, stage });
  if (!eligibility.eligible) throw new Error(eligibility.reason);
  const assignment = candidate.classification?.editorial_assignment || {};
  const writer = writerSelection || run.writer_selection || (assignment.writer ? { writer: assignment.writer, length: assignment.length, model: assignment.writer_model, reasoning: assignment.writer_reasoning } : null);
  if (!writer?.writer || !writer?.length) throw new Error('Replay requires the original writer and length assignment.');
  return {
    job_id: jobId || null,
    action: 'replay_from_stage',
    replay_from_stage: stage,
    parent_run_id: run.id,
    replay_attempt_id: uuid(),
    pipeline_version: 'v1',
    writer: writer.writer,
    length: writer.length,
    writer_model: writer.model || null,
    writer_reasoning: writer.reasoning || null,
    research_requirement: run.research_requirement || candidate.classification?.editorial_pitch?.research_requirement || null,
    research_requirement_reason: run.research_requirement_reason || null
  };
}

export function copyReplayArtifacts({ state, previousRun, run, stage }) {
  const plan = replayPlan(stage);
  const sourceArtifacts = (state.phase2_artifacts || []).filter(item => item.case_run_id === (previousRun.case_run_id || previousRun.id) && plan.reuse.includes(item.stage) && item.status === 'complete');
  const copied = sourceArtifacts.map(artifact => ({
    ...artifact,
    id: uuid(),
    case_run_id: run.case_run_id || run.id,
    pipeline_run_id: run.id,
    replay_reused: true,
    reused_from_artifact_id: artifact.id,
    created_at: new Date().toISOString(),
    payload: artifact.payload && typeof artifact.payload === 'object'
      ? { ...artifact.payload, case_run_id: run.case_run_id || run.id, run_status: 'running', run_state: 'commissioned' }
      : artifact.payload
  }));
  const parentAttempts = Object.fromEntries((previousRun.attempts || []).filter(attempt => plan.reuse.includes(attempt.stage)).map(attempt => [attempt.stage, attempt.id]));
  state.phase2_artifacts.push(...copied);
  for (const artifact of copied) run.stage_results[artifact.stage] = artifact.id;
  run.replay = { requested_stage: stage, parent_run_id: previousRun.id, replay_attempt_id: run.replay_attempt_id || null, parent_attempt_ids: parentAttempts, reused_artifacts: copied.map(item => ({ stage: item.stage, artifact_id: item.id, source_artifact_id: item.reused_from_artifact_id })), rerun_stages: plan.rerun };
  run.events.push({ type: 'replay_started', stage, parent_run_id: previousRun.id, reused_stages: copied.map(item => item.stage), rerun_stages: plan.rerun, at: new Date().toISOString() });
  return copied;
}
